[asy]
unitsize(0.3 cm);

pair A, B, C, D, M;

A = (-7/sqrt(37),42/sqrt(37));
B = (0,0);
C = (2*sqrt(37),0);
M = (B + C)/2;
D = 2*M - A;

draw(A--B--C--cycle);
draw(A--D--C);

label("$A$", A, dir(90));
label("$B$", B, SW);
label("$C$", C, NE);
label("$D$", D, S);
